  private fn: T;
  private timeoutId: number | null = null;
  private options: DebounceOptions<T> = {};
  private isCancelled: boolean = false;

  constructor(fn: T, options?: DebounceOptions<T>) {
    this.fn = fn;
    this.options = {
      delay: options?.delay ?? 0,
      onResolve: options?.onResolve,
      onCancel: options?.onCancel,
    };
  }

  public cancel(): void {
    if (this.timeoutId !== null) {
      clearTimeout(this.timeoutId);
      this.timeoutId = null;
      this.isCancelled = true;
    }
  }

  public resolve(): void {
    if (this.isCancelled) {
      this.cancel();
      this.fn(); // Re-execute the function
    } else {
      clearTimeout(this.timeoutId);
      this.timeoutId = setTimeout(() => {
        this.isCancelled = false;
        this.fn();
        if (this.options.onResolve) {
          this.options.onResolve(this.fn(...arguments));
        }
      }, this.options.delay);
    }
  }

  public invoke(...args: Parameters<T>): void {
    if (this.isCancelled) {
      return;
    }

    if (this.timeoutId) {
